contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint amount) public payable {
        // Provide some Ether to c so withdrawAll has something to transfer.
        require(amount > 0);
        require(address(this).balance >= amount);
        c.sendMoney(address(c), amount);

        // The test contract deployed c, so it is the owner.
        address owner = c.owner();
        require(owner == address(this));

        // Before state
        uint beforeOwner = address(this).balance;
        uint beforeContract = address(c).balance;

        bool reverted;
        try c.withdrawAll() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Rule: if withdrawAll succeeds, the contract balance becomes zero,
        // the owner received the entire previous contract balance, and thus
        // the owner's balance increased by exactly beforeContract.
        if (!reverted) {
            assert(address(c).balance == 0);
            assert(address(this).balance == beforeOwner + beforeContract);
        } else {
            // If it reverts, the contract balance must remain unchanged.
            assert(address(c).balance == beforeContract);
        }
    }

    receive() external payable {}
}

